-- D-090: somente colunas opcionais. Nenhum backfill, alteração de tipo ou carga da planilha.
ALTER TABLE units ADD COLUMN official_name TEXT CHECK (official_name IS NULL OR (length(official_name)<=180));
ALTER TABLE units ADD COLUMN secretary_name TEXT CHECK (secretary_name IS NULL OR (length(secretary_name)<=180));
ALTER TABLE units ADD COLUMN school_zone TEXT CHECK (school_zone IS NULL OR (school_zone IN ('Urbana','Rural')));
ALTER TABLE units ADD COLUMN school_shifts TEXT CHECK (school_shifts IS NULL OR (length(school_shifts)<=120));
ALTER TABLE units ADD COLUMN full_time TEXT CHECK (full_time IS NULL OR (full_time IN ('Sim','Não')));
ALTER TABLE units ADD COLUMN shared_building TEXT CHECK (shared_building IS NULL OR (shared_building IN ('Sim','Não')));
ALTER TABLE units ADD COLUMN pdde_status TEXT CHECK (pdde_status IS NULL OR (pdde_status IN ('Ativo','Pendente','Não se aplica')));
ALTER TABLE units ADD COLUMN census_pending TEXT CHECK (census_pending IS NULL OR (census_pending IN ('Sim','Não')));
ALTER TABLE units ADD COLUMN sports_court TEXT CHECK (sports_court IS NULL OR (sports_court IN ('Sim','Não')));
ALTER TABLE units ADD COLUMN video_monitoring TEXT CHECK (video_monitoring IS NULL OR (video_monitoring IN ('Sim','Não')));
ALTER TABLE units ADD COLUMN classrooms_total INTEGER CHECK (classrooms_total IS NULL OR (classrooms_total BETWEEN 0 AND 99999 AND typeof(classrooms_total)='integer'));
ALTER TABLE units ADD COLUMN classrooms_in_use INTEGER CHECK (classrooms_in_use IS NULL OR (classrooms_in_use BETWEEN 0 AND 99999 AND typeof(classrooms_in_use)='integer'));
